#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>

int main() {
  pid_t pid = fork();
  if (pid < 0) {
    perror("fork failed");
    return 1;
  }
  else if (pid == 0) {
    printf("Child process: PID = %d\n", getpid());
    // Child process code
    sleep(2); // Simulate work
  }
  else {
    printf("Parent process: PID = %d\n", getpid());
    // Parent process code
    sleep(1); // Simulate work
  }
  return 0;
}
